USE radicalgym;

UPDATE empleados SET biografia = 'Certificado IFBB Pro Coach con más de 8 años guiando atletas y principiantes en ganancia muscular y recomposición corporal.', calificacion = 4.9, horario_disponible = 'Lun - Sáb: 6:00 AM - 2:00 PM', foto = 'https://images.unsplash.com/photo-1567013127542-490d757e51fc?w=400&auto=format&fit=crop&q=80', titulo_cargo = 'Hipertrofia & Fuerza Máxima' WHERE idempleado = 1002;
UPDATE empleados SET biografia = 'Licenciada en Ciencias del Deporte, especialista en HIIT, entrenamiento metabólico y nutrición aplicada.', calificacion = 5, horario_disponible = 'Lun - Vie: 2:00 PM - 10:00 PM', foto = 'https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=400&auto=format&fit=crop&q=80', titulo_cargo = 'Pérdida de Grasa & Acondicionamiento' WHERE idempleado = 1003;
UPDATE empleados SET biografia = 'Especialista en movilidad articular, técnica de levantamientos pesados (sentadilla, press banca, peso muerto) y dominadas lastradas.', calificacion = 4.8, horario_disponible = 'Lun - Sáb: 7:00 AM - 3:00 PM', foto = 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=400&auto=format&fit=crop&q=80', titulo_cargo = 'Powerlifting & Calistenia' WHERE idempleado = 1006;
UPDATE empleados SET titulo_cargo = CASE cargo WHEN 'administrador' THEN 'Gerente General' WHEN 'recepcion' THEN 'Recepcionista y Caja'
  WHEN 'nutricionista' THEN 'Lic. en Nutrición Deportiva' WHEN 'fisioterapeuta' THEN 'Fisioterapeuta Especialista' ELSE titulo_cargo END WHERE titulo_cargo IS NULL;
UPDATE planes SET caracteristicas = 'Acceso a sala de pesas y cardio|Uso de vestuarios y duchas|Evaluación inicial' WHERE nombre = 'Mensual';
UPDATE planes SET caracteristicas = 'Todo lo del plan mensual|1 evaluación nutricional|Congelamiento de 7 días', destacado = 1 WHERE nombre = 'Trimestral';
UPDATE planes SET caracteristicas = 'Entrenador asignado|Control nutricional mensual|Congelamiento de 15 días' WHERE nombre = 'Semestral';
UPDATE planes SET caracteristicas = 'Todo incluido|Fisioterapia preventiva|Congelamiento de 30 días|Polo de regalo' WHERE nombre = 'Anual';
UPDATE planes SET caracteristicas = 'Acceso total|Entrenador personal 3 veces por semana' WHERE nombre = 'Mensual Plus';
UPDATE productos SET marca = 'Radical', descripcion = 'Producto oficial de la tienda Radical Gym';


