UPDATE alumnos SET idrutina = 1 WHERE idalumno IN (1000, 1006, 1012, 1018);
UPDATE alumnos SET idrutina = 2 WHERE idalumno IN (1001, 1004, 1011);




UPDATE codigos_spinning c JOIN alumnos a ON a.idalumno = c.idalumno SET c.nombre = CONCAT(a.nombres,' ',a.apellidos), c.telefono = a.telefono;



SELECT c.idcontrato, DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), '%Y-%m'), c.sueldo_mensual, c.horas_semanales * 4.33, c.tarifa_hora
  FROM contratos c WHERE c.estado <> 'renovado';
SELECT c.idcontrato, DATE_FORMAT(CURDATE(), '%Y-%m'), c.sueldo_mensual,
       IFNULL((SELECT SUM(horas_trabajadas) FROM asistencias_empleado s WHERE s.idempleado = c.idempleado AND DATE_FORMAT(s.fecha,'%Y-%m') = DATE_FORMAT(CURDATE(),'%Y-%m')),0),
       c.tarifa_hora
  FROM contratos c WHERE c.estado <> 'renovado';
-- El pago del mes anterior genera los egresos de sueldo por trigger
UPDATE planilla SET estado = 'pagado', metodo_pago = 'transferencia', fecha_pago = DATE_SUB(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 2 DAY)
 WHERE periodo = DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), '%Y-%m');
DELETE FROM movimientos_caja WHERE categoria = 'planilla' AND descripcion = 'Pago a Diego Salazar';

-- Notificaciones enviadas con canal y destinatario
UPDATE notificaciones SET canal = 'push', publico = destino;
UPDATE notificaciones n JOIN alumnos a ON a.idalumno = n.idalumno
   SET n.destinatario_nombre = CONCAT(a.nombres,' ',a.apellidos), n.destinatario_correo = a.correo, n.destinatario_telefono = a.telefono, n.canal = 'whatsapp';
