INSERT INTO ejercicios (nombre, grupo_muscular, musculos_secundarios, equipo, dificultad, instrucciones, consejos, series_repeticiones, video_url, miniatura_url) VALUES
('Press de Banca Plano con Barra', 'pecho', 'Tríceps|Deltoides anterior', 'barra', 'intermedio', 'Acuéstate sobre el banco plano con los pies firmes en el suelo. Retrae las escápulas, desciende la barra de forma controlada al pecho medio y empuja explosivamente hacia arriba sin bloquear codos bruscamente.', 'Mantén un arco lumbar natural y los codos en ángulo de 45-60 grados respecto al torso.', '4 series x 8-10 reps', 'https://www.youtube.com/watch?v=rT7DgCr-3pg', 'https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?w=400&auto=format&fit=crop&q=80'),
('Press Inclinado con Mancuernas', 'pecho', 'Deltoides anterior|Tríceps', 'mancuernas', 'intermedio', 'Banco a 30-45 grados. Sube las mancuernas con control, estira el pectoral en el fondo y contrae arriba sin chocar las mancuernas.', 'Excelente para enfatizar la porción clavicular del pectoral.', '4 series x 10-12 reps', 'https://www.youtube.com/watch?v=8iPEnn-ltC8', 'https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?w=400&auto=format&fit=crop&q=80'),
('Aperturas en Poleas (Cruces)', 'pecho', 'Deltoides anterior', 'polea', 'principiante', 'Coloca las poleas a media o alta altura. Da un paso al frente con el torso levemente inclinado y junta las manos frente al pecho apretando 1 segundo.', 'Mantén una ligera flexión constante de codos durante todo el recorrido.', '3 series x 12-15 reps', 'https://www.youtube.com/watch?v=taI4XduLpBe', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=400&auto=format&fit=crop&q=80'),
('Fondos en Paralelas para Pecho', 'pecho', 'Tríceps|Hombros', 'peso_corporal', 'avanzado', 'Inclina el torso 30 grados hacia adelante y baja hasta que los codos formen 90 grados, sintiendo el estiramiento en el pectoral.', 'Evita descender en exceso si tienes molestias en el hombro.', '3 series x 8-12 reps', 'https://www.youtube.com/watch?v=2z8JmcrW-As', 'https://images.unsplash.com/photo-1598971639058-fab3c3109a00?w=400&auto=format&fit=crop&q=80'),
('Dominadas Pronas (Pull-ups)', 'espalda', 'Bíceps|Braquial|Core', 'peso_corporal', 'avanzado', 'Agarre más ancho que los hombros. Tira con los codos hacia abajo llevando el pecho a la barra y desciende lentamente.', 'No te balancees; activa la espalda antes de flexionar los brazos.', '4 series x 6-10 reps', 'https://www.youtube.com/watch?v=eGo4IYlbE5g', 'https://images.unsplash.com/photo-1526506118085-60ce8714f8c5?w=400&auto=format&fit=crop&q=80'),
('Jalón al Pecho en Polea Alta', 'espalda', 'Bíceps|Dorsal ancho', 'polea', 'principiante', 'Sujeta la barra ancha, reclina el torso 10 grados y lleva la barra hacia la parte superior del esternón sacando pecho.', 'Imagina que tiras desde los codos, no desde las muñecas.', '4 series x 10-12 reps', 'https://www.youtube.com/watch?v=CAwf7n6Luuc', 'https://images.unsplash.com/photo-1605296867304-46d5465a13f1?w=400&auto=format&fit=crop&q=80'),
('Remo con Barra Inclinado (Pendlay / Tradicional)', 'espalda', 'Erectores espinales|Trapecio|Bíceps', 'barra', 'intermedio', 'Espalda recta paralela o a 45 grados del suelo. Tira de la barra hacia el ombligo apretando las escápulas.', 'Aprieta el abdomen para proteger la zona lumbar.', '4 series x 8-10 reps', 'https://www.youtube.com/watch?v=G8l_8chR5BE', 'https://images.unsplash.com/photo-1541534741688-6078c6bfb5c5?w=400&auto=format&fit=crop&q=80'),
('Remo Gironda en Polea Baja', 'espalda', 'Bíceps|Romboide', 'polea', 'principiante', 'Agarre en V, mantén la espalda erguida y lleva el agarre al abdomen manteniendo los codos pegados.', 'Pausa de 1 segundo en la máxima contracción.', '3 series x 12 reps', 'https://www.youtube.com/watch?v=GZbfZ033f74', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=400&auto=format&fit=crop&q=80'),
('Sentadilla Trasera con Barra (Back Squat)', 'cuadriceps', 'Glúteos|Isquiotibiales|Core', 'barra', 'intermedio', 'Barra sobre los trapecios. Desciende flexionando caderas y rodillas hasta romper el paralelo (90 grados) y sube con fuerza empujando el suelo.', 'Mantén las rodillas alineadas con la punta de los pies y la mirada al frente.', '4 series x 6-8 reps', 'https://www.youtube.com/watch?v=bEv6CCg2BC8', 'https://images.unsplash.com/photo-1574680096145-d05b474e2155?w=400&auto=format&fit=crop&q=80'),
('Prensa de Piernas 45 Grados', 'cuadriceps', 'Glúteos', 'maquina', 'principiante', 'Pies al ancho de hombros en la plataforma. Baja el peso flexionando rodillas sin despegar el coxis del respaldo y empuja sin bloquear las rodillas al final.', 'Nunca bloquees las rodillas por completo en la extensión.', '4 series x 10-12 reps', 'https://www.youtube.com/watch?v=IZxyjW7MPJQ', 'https://images.unsplash.com/photo-1534367507873-d2d7e24c797f?w=400&auto=format&fit=crop&q=80'),
('Extensión de Cuádriceps en Máquina', 'cuadriceps', NULL, 'maquina', 'principiante', 'Ajusta el cojín sobre los tobillos. Extiende las piernas contrayendo los cuádriceps arriba durante 1 segundo y baja lentamente.', 'Excelente ejercicio para aislamiento previo o finalizador.', '3 series x 12-15 reps', 'https://www.youtube.com/watch?v=YyvSfVjQeL0', 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?w=400&auto=format&fit=crop&q=80'),
('Búlgaras con Mancuernas', 'cuadriceps', 'Glúteos|Estabilizadores', 'mancuernas', 'avanzado', 'Un pie apoyado atrás en un banco y la pierna delantera adelantada. Desciende verticalmente hasta que la rodilla trasera roce el suelo.', 'Inclinar un poco el torso potencia el trabajo de glúteo.', '3 series x 10 reps por pierna', 'https://www.youtube.com/watch?v=2C-uNgKwPLE', 'https://images.unsplash.com/photo-1434682881908-b43d0467b798?w=400&auto=format&fit=crop&q=80'),
('Hip Thrust con Barra (Empuje de Cadera)', 'isquiotibiales_gluteos', 'Isquios|Core', 'barra', 'intermedio', 'Espalda superior apoyada en un banco, barra acolchada sobre las caderas. Eleva la pelvis empujando con los talones hasta alinear torso y muslos.', 'Apreta los glúteos en el tope 2 segundos y mete la barbilla al pecho.', '4 series x 8-12 reps', 'https://www.youtube.com/watch?v=SEdqd1n0cvg', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=400&auto=format&fit=crop&q=80'),
('Peso Muerto Rumano con Mancuernas / Barra', 'isquiotibiales_gluteos', 'Erectores|Espalda alta', 'barra', 'intermedio', 'Rodillas semiflexionadas y fijas. Empuja las caderas hacia atrás sintiendo un gran estiramiento en los femorales y regresa contrayendo glúteos.', 'La barra debe deslizarse rozando las piernas todo el tiempo.', '4 series x 10-12 reps', 'https://www.youtube.com/watch?v=JCXUYuzwNrM', 'https://images.unsplash.com/photo-1532384748853-8f54a8f476e2?w=400&auto=format&fit=crop&q=80'),
('Curl Femoral Tumbado en Máquina', 'isquiotibiales_gluteos', 'Pantorrillas', 'maquina', 'principiante', 'Boca abajo con el rodillo en la parte posterior de los tobillos. Flexiona las rodillas llevando los talones a los glúteos de manera controlada.', 'Mantén la pelvis pegada a la banca para no trampear con la zona lumbar.', '3 series x 12-15 reps', 'https://www.youtube.com/watch?v=1Tq3EDRy_yU', 'https://images.unsplash.com/photo-1583454110551-21f2fa2afe61?w=400&auto=format&fit=crop&q=80'),
('Press Militar con Mancuernas Sentado', 'hombros', 'Tríceps|Trapecio', 'mancuernas', 'intermedio', 'Sentado con respaldo a 80-90 grados. Empuja las mancuernas por encima de la cabeza y bájalas a la altura de las orejas.', 'Evita arquear excesivamente la zona lumbar.', '4 series x 8-10 reps', 'https://www.youtube.com/watch?v=qEwKCR5JCog', 'https://images.unsplash.com/photo-1581009137042-c552e485697a?w=400&auto=format&fit=crop&q=80'),
('Elevaciones Laterales con Mancuernas', 'hombros', 'Trapecio', 'mancuernas', 'principiante', 'De pie o sentado, eleva los brazos lateralmente con los codos ligeramente flexionados hasta la altura de los hombros.', 'Lidera el movimiento con los codos y no uses impulso con el cuerpo.', '4 series x 12-15 reps', 'https://www.youtube.com/watch?v=3VcKaXpzqRo', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=400&auto=format&fit=crop&q=80'),
('Face Pulls en Polea Alta con Cuerda', 'hombros', 'Manguito rotador|Deltoides posterior|Trapecio', 'polea', 'principiante', 'Tira de la cuerda hacia la cara/ojos, rotando externamente los hombros de modo que los nudillos apunten hacia atrás.', 'Fundamental para la salud y postura del hombro.', '3 series x 15 reps', 'https://www.youtube.com/watch?v=rep-qVOkqgk', 'https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=400&auto=format&fit=crop&q=80'),
('Curl de Bíceps con Barra Z', 'biceps', 'Antebrazos', 'barra', 'principiante', 'De pie con agarre supino en los ángulos de la barra Z. Flexiona los codos sin mover los hombros hacia adelante y baja en 2 segundos.', 'La barra Z reduce la tensión en las muñecas.', '3 series x 10-12 reps', 'https://www.youtube.com/watch?v=in7PaeYlhrM', 'https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?w=400&auto=format&fit=crop&q=80'),
('Curl Martillo con Mancuernas', 'biceps', 'Braquial|Braquiorradial', 'mancuernas', 'principiante', 'Agarre neutro (palmas enfrentadas). Eleva las mancuernas para desarrollar el grosor del brazo.', 'Puedes hacerlo alterno o simultáneo.', '3 series x 12 reps', 'https://www.youtube.com/watch?v=zC3nLlEvin4', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=400&auto=format&fit=crop&q=80'),
('Extensiones de Tríceps en Polea Alta con Cuerda', 'triceps', NULL, 'polea', 'principiante', 'Codos pegados a los costados. Empuja la cuerda hacia abajo y separa los extremos al final para máxima contracción.', 'No muevas los codos de posición fija.', '4 series x 12-15 reps', 'https://www.youtube.com/watch?v=vB5OHsJ3EME', 'https://images.unsplash.com/photo-1605296867304-46d5465a13f1?w=400&auto=format&fit=crop&q=80'),
('Press Francés con Mancuernas en Banco', 'triceps', NULL, 'mancuernas', 'intermedio', 'Acuéstate en el banco con mancuernas en alto. Flexiona únicamente los codos bajando las mancuernas a los lados de la frente y extiende.', 'Gran énfasis en la cabeza larga del tríceps.', '3 series x 10-12 reps', 'https://www.youtube.com/watch?v=d_KZxkY_0cM', 'https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?w=400&auto=format&fit=crop&q=80'),
('Plancha Abdominal Isométrica (Plank)', 'core_abdomen', 'Glúteos|Hombros', 'peso_corporal', 'principiante', 'Apoyo en antebrazos y puntas de pie. Cuerpo en línea recta perfecta sin hundir ni elevar la cadera.', 'Activa el transverso y glúteos activamente.', '3 series x 45-60 segundos', 'https://www.youtube.com/watch?v=ASdvN_XEl_c', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=400&auto=format&fit=crop&q=80'),
('Elevaciones de Piernas Colgado en Barra', 'core_abdomen', 'Flexores de cadera', 'peso_corporal', 'avanzado', 'Colgado de la barra, eleva las piernas rectas o flexionadas hacia el pecho contrayendo el abdomen.', 'Controla el descenso para no generar balanceo.', '3 series x 12-15 reps', 'https://www.youtube.com/watch?v=hdng3Nm1x_E', 'https://images.unsplash.com/photo-1526506118085-60ce8714f8c5?w=400&auto=format&fit=crop&q=80'),
('Rueda Abdominal (Ab Wheel Rollout)', 'core_abdomen', 'Dorsales|Hombros', 'otro', 'avanzado', 'De rodillas, rueda hacia adelante manteniendo la espalda ligeramente redondeada y regresa contrayendo el core.', 'No permitas que la zona lumbar se arquee en la extensión.', '3 series x 8-12 reps', 'https://www.youtube.com/watch?v=rqiTPdK1c_I', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=400&auto=format&fit=crop&q=80'),
('Burpees con Salto', 'cardio_funcional', 'Pecho|Piernas|Core', 'peso_corporal', 'intermedio', 'Baja a posición de plancha, haz una flexión, recupera los pies y salta verticalmente con los brazos arriba.', 'Ritmo constante para elevar la frecuencia cardíaca.', '4 series x 15 reps o 45 segs', 'https://www.youtube.com/watch?v=auBLPXO8Fww', 'https://images.unsplash.com/photo-1598971639058-fab3c3109a00?w=400&auto=format&fit=crop&q=80'),
('Kettlebell Swings (Balanceo con Pesa Rusa)', 'cardio_funcional', 'Glúteos|Isquios|Espalda baja|Hombros', 'kettlebell', 'intermedio', 'Bisagra de cadera explosiva. El impulso viene de los glúteos e isquiotibiales, no de los brazos.', 'Mantén la columna neutra durante toda la trayectoria.', '4 series x 20 reps', 'https://www.youtube.com/watch?v=sSESeQAir2M', 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?w=400&auto=format&fit=crop&q=80'),
('Intervalos en Assault Bike / Remo Concept2', 'cardio_funcional', 'Cuerpo completo', 'maquina', 'intermedio', 'Sprints de 20 segundos a máxima intensidad seguidos de 40 segundos de pedaleo suave de recuperación.', 'Ideal para acondicionamiento metabólico post-entrenamiento.', '8 a 10 rondas de intervalos', 'https://www.youtube.com/watch?v=gT8_qQe5W44', 'https://images.unsplash.com/photo-1534367507873-d2d7e24c797f?w=400&auto=format&fit=crop&q=80');
INSERT INTO rutinas (titulo, descripcion, nivel, objetivo, identrenador, idalumno, fecha) VALUES ('Rutina Hipertrofia PPL (Empuje, Tirón, Pierna)', 'Programa clásico enfocado en máxima ganancia de masa muscular con excelente frecuencia y volumen equilibrado.', 'intermedio', 'hipertrofia', 1002, NULL, DATE_ADD(CURDATE(), INTERVAL -29 DAY));
INSERT INTO rutina_dias (idrutina, orden, nombre, enfoque, notas) VALUES (@rutina, 1, 'Día 1: Empuje (Pecho, Hombro anterior/lateral, Tríceps)', 'Pectorales y tríceps con énfasis en fuerza e hipertrofia', 'Calentar 5 minutos antes y realizar series de aproximación en banca.');
