(1, 1, 1, 'lateral', 'Keiser M3i Indoor Cycle', 1, 1, NULL),
(2, 1, 2, 'frontal', 'Keiser M3i Indoor Cycle', 1, 1, NULL),
(3, 1, 3, 'frontal', 'Keiser M3i Indoor Cycle', 1, 1, NULL),
(4, 1, 4, 'frontal', 'Keiser M3i Indoor Cycle', 1, 1, NULL),
